// Notes app in C on the platform: HTTP from wasi:http, storage from
// platform:sdk/sql (SQLite), a view counter from platform:sdk/cache.
//
//   GET  /cnotes        latest notes and the view count (JSON)
//   POST /cnotes        add a note; the body is its text
//
// Bindings are generated by `wit-bindgen c` into gen/.

#include "gen/app.h"

#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define DB "notes"
#define MAX_BODY (16 * 1024)

// ---------------------------------------------------------------- buffer

typedef struct {
    char *data;
    size_t len, cap;
} buf_t;

static void buf_put(buf_t *b, const char *s, size_t n) {
    if (b->len + n > b->cap) {
        b->cap = (b->len + n) * 2 + 64;
        b->data = realloc(b->data, b->cap);
    }
    memcpy(b->data + b->len, s, n);
    b->len += n;
}

static void buf_str(buf_t *b, const char *s) { buf_put(b, s, strlen(s)); }

static void buf_fmt(buf_t *b, const char *fmt, ...) {
    char tmp[256];
    va_list args;
    va_start(args, fmt);
    int n = vsnprintf(tmp, sizeof tmp, fmt, args);
    va_end(args);
    buf_put(b, tmp, n < (int)sizeof tmp ? (size_t)n : sizeof tmp - 1);
}

// A JSON string literal, escaped.
static void buf_json(buf_t *b, const uint8_t *s, size_t n) {
    buf_put(b, "\"", 1);
    for (size_t i = 0; i < n; i++) {
        uint8_t c = s[i];
        if (c == '"' || c == '\\') {
            buf_put(b, "\\", 1);
            buf_put(b, (const char *)&c, 1);
        } else if (c < 0x20) {
            buf_fmt(b, "\\u%04x", c);
        } else {
            buf_put(b, (const char *)&c, 1);
        }
    }
    buf_put(b, "\"", 1);
}

// ---------------------------------------------------------------- http

static void respond(wasi_http_types_own_response_outparam_t out, uint16_t status, buf_t *body) {
    wasi_http_types_tuple2_field_name_field_value_t header;
    app_string_set(&header.f0, "content-type");
    header.f1.ptr = (uint8_t *)"application/json";
    header.f1.len = strlen("application/json");
    wasi_http_types_list_tuple2_field_name_field_value_t list = {&header, 1};
    wasi_http_types_own_fields_t headers;
    wasi_http_types_header_error_t header_err;
    if (!wasi_http_types_static_fields_from_list(&list, &headers, &header_err)) {
        headers = wasi_http_types_constructor_fields();
    }

    wasi_http_types_own_outgoing_response_t resp = wasi_http_types_constructor_outgoing_response(headers);
    wasi_http_types_method_outgoing_response_set_status_code(wasi_http_types_borrow_outgoing_response(resp), status);
    wasi_http_types_own_outgoing_body_t out_body;
    wasi_http_types_method_outgoing_response_body(wasi_http_types_borrow_outgoing_response(resp), &out_body);

    wasi_http_types_result_own_outgoing_response_error_code_t result = {.is_err = false, .val.ok = resp};
    wasi_http_types_static_response_outparam_set(out, &result);

    wasi_http_types_own_output_stream_t stream;
    wasi_http_types_method_outgoing_body_write(wasi_http_types_borrow_outgoing_body(out_body), &stream);
    // blocking-write-and-flush takes at most 4096 bytes at a time.
    for (size_t off = 0; off < body->len; off += 4096) {
        size_t n = body->len - off < 4096 ? body->len - off : 4096;
        app_list_u8_t chunk = {(uint8_t *)body->data + off, n};
        wasi_io_streams_stream_error_t err;
        if (!wasi_io_streams_method_output_stream_blocking_write_and_flush(wasi_io_streams_borrow_output_stream(stream), &chunk, &err)) {
            break;
        }
    }
    wasi_io_streams_output_stream_drop_own(stream);
    wasi_http_types_error_code_t finish_err;
    wasi_http_types_static_outgoing_body_finish(out_body, NULL, &finish_err);
}

static void respond_error(wasi_http_types_own_response_outparam_t out, uint16_t status, const char *message) {
    buf_t b = {0};
    buf_str(&b, "{\"error\":");
    buf_json(&b, (const uint8_t *)message, strlen(message));
    buf_str(&b, "}");
    respond(out, status, &b);
    free(b.data);
}

// Reads the request body (up to MAX_BODY). Returns false if it's too large.
static bool read_body(wasi_http_types_borrow_incoming_request_t req, buf_t *b) {
    wasi_http_types_own_incoming_body_t body;
    if (!wasi_http_types_method_incoming_request_consume(req, &body)) return false;
    wasi_http_types_own_input_stream_t stream;
    if (!wasi_http_types_method_incoming_body_stream(wasi_http_types_borrow_incoming_body(body), &stream)) return false;
    bool ok = true;
    for (;;) {
        app_list_u8_t chunk;
        wasi_io_streams_stream_error_t err;
        if (!wasi_io_streams_method_input_stream_blocking_read(wasi_io_streams_borrow_input_stream(stream), 65536, &chunk, &err)) {
            break;  // closed (end of body) or failed
        }
        if (b->len + chunk.len > MAX_BODY) ok = false;
        else buf_put(b, (const char *)chunk.ptr, chunk.len);
        app_list_u8_free(&chunk);
        if (!ok) break;
    }
    wasi_io_streams_input_stream_drop_own(stream);
    wasi_http_types_future_trailers_drop_own(wasi_http_types_static_incoming_body_finish(body));
    return ok;
}

// ---------------------------------------------------------------- app

static const char *sql_error(platform_sdk_sql_error_t *e) {
    static char msg[200];
    app_string_t *s = NULL;
    switch (e->tag) {
        case PLATFORM_SDK_SQL_ERROR_NOT_ALLOWED: s = &e->val.not_allowed; break;
        case PLATFORM_SDK_SQL_ERROR_UNAVAILABLE: s = &e->val.unavailable; break;
        case PLATFORM_SDK_SQL_ERROR_QUERY: s = &e->val.query; break;
        case PLATFORM_SDK_SQL_ERROR_CONVERSION: s = &e->val.conversion; break;
        default: return "database error";
    }
    snprintf(msg, sizeof msg, "%.*s", (int)s->len, (const char *)s->ptr);
    return msg;
}

static void list_notes(wasi_http_types_own_response_outparam_t out) {
    app_string_t key;
    app_string_set(&key, "views");
    int64_t views = platform_sdk_cache_incr(&key, 1, 0);

    app_string_t db, sql;
    app_string_set(&db, DB);
    app_string_set(&sql, "SELECT id, text, at FROM notes ORDER BY id DESC LIMIT 20");
    platform_sdk_sql_list_value_t params = {NULL, 0};
    platform_sdk_sql_query_result_t result;
    platform_sdk_sql_error_t err;
    if (!platform_sdk_sql_query(&db, &sql, &params, &result, &err)) {
        respond_error(out, 500, sql_error(&err));
        platform_sdk_sql_error_free(&err);
        return;
    }

    buf_t b = {0};
    buf_fmt(&b, "{\"views\":%lld,\"notes\":[", (long long)views);
    for (size_t i = 0; i < result.rows.len; i++) {
        platform_sdk_sql_value_t *row = result.rows.ptr[i].ptr;
        if (i > 0) buf_str(&b, ",");
        buf_fmt(&b, "{\"id\":%lld,\"text\":", (long long)row[0].val.int_);
        buf_json(&b, row[1].val.text.ptr, row[1].val.text.len);
        buf_fmt(&b, ",\"at\":%lld}", (long long)row[2].val.int_);
    }
    buf_str(&b, "]}");
    respond(out, 200, &b);
    free(b.data);
    platform_sdk_sql_query_result_free(&result);
}

static void add_note(wasi_http_types_borrow_incoming_request_t req, wasi_http_types_own_response_outparam_t out) {
    buf_t text = {0};
    if (!read_body(req, &text)) {
        free(text.data);
        respond_error(out, 413, "note too long");
        return;
    }
    if (text.len == 0) {
        respond_error(out, 422, "empty note");
        return;
    }

    platform_sdk_sql_value_t values[2];
    values[0].tag = PLATFORM_SDK_SQL_VALUE_TEXT;
    values[0].val.text.ptr = (uint8_t *)text.data;
    values[0].val.text.len = text.len;
    values[1].tag = PLATFORM_SDK_SQL_VALUE_INT;
    values[1].val.int_ = (int64_t)time(NULL);
    platform_sdk_sql_list_value_t params = {values, 2};

    app_string_t db, sql;
    app_string_set(&db, DB);
    app_string_set(&sql, "INSERT INTO notes (text, at) VALUES ($1, $2) RETURNING id");
    platform_sdk_sql_query_result_t result;
    platform_sdk_sql_error_t err;
    bool ok = platform_sdk_sql_query(&db, &sql, &params, &result, &err);
    free(text.data);
    if (!ok) {
        respond_error(out, 500, sql_error(&err));
        platform_sdk_sql_error_free(&err);
        return;
    }
    buf_t b = {0};
    buf_fmt(&b, "{\"id\":%lld}", (long long)result.rows.ptr[0].ptr[0].val.int_);
    respond(out, 201, &b);
    free(b.data);
    platform_sdk_sql_query_result_free(&result);
}

void exports_wasi_http_incoming_handler_handle(
    exports_wasi_http_incoming_handler_own_incoming_request_t request,
    exports_wasi_http_incoming_handler_own_response_outparam_t response_out) {
    wasi_http_types_borrow_incoming_request_t req = wasi_http_types_borrow_incoming_request(request);
    wasi_http_types_method_t method;
    wasi_http_types_method_incoming_request_method(req, &method);
    app_string_t path = {0};
    wasi_http_types_method_incoming_request_path_with_query(req, &path);

    bool root = path.len >= 7 && memcmp(path.ptr, "/cnotes", 7) == 0 &&
                (path.len == 7 || path.ptr[7] == '?' || (path.len == 8 && path.ptr[7] == '/'));
    if (root && method.tag == WASI_HTTP_TYPES_METHOD_GET) {
        list_notes(response_out);
    } else if (root && method.tag == WASI_HTTP_TYPES_METHOD_POST) {
        add_note(req, response_out);
    } else {
        respond_error(response_out, 404, "not found");
    }
    app_string_free(&path);
    wasi_http_types_method_free(&method);
    wasi_http_types_incoming_request_drop_own(request);
}
